    t = TYPES.get(str(p.get(TYPE_FIELD) or '')) or dict()
    s = str(t.get('spoken') or str(p.get(TYPE_FIELD) or 'product').replace('_', ' '))
    for k, v in p.items():
        s = s.replace('{' + str(k) + '}', str(v))
    return s
