    for _ in range(400):
        if isbiz(x):
            return x
        x = x + TD(days=1)
    return x
def nth_biz_after(d, n):
    x = d
    k = 1 if (CAL.get('count_today') and isbiz(d)) else 0
    for _ in range(400):
        if k >= n:
            return x
        x = x + TD(days=1)
        if isbiz(x):
            k += 1
    return x
def week_end_biz(d):
    """Last business day of d's calendar week (Monday to Sunday), or None if there is none."""
    monday = d - TD(days=d.weekday())
    x = monday + TD(days=6)
    while x >= monday:
        if isbiz(x):
            return x
        x = x - TD(days=1)
    return None
