import datetime, json
CAL = json.loads('{"holidays":["2026-10-26","2026-11-11","2026-11-26","2026-12-25","2027-01-01"],"weekend":[5,6],"count_today":false}')
HOL = set(CAL.get('holidays') or [])
WEEKEND = set(CAL.get('weekend') if CAL.get('weekend') is not None else [5, 6])
DN = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
MN = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
D = datetime.date
TD = datetime.timedelta
def isbiz(d):
    return d.weekday() not in WEEKEND and d.isoformat() not in HOL
def sp(d):
    return DN[d.weekday()] + ' ' + str(d.day) + ' ' + MN[d.month - 1] + ' ' + str(d.year)
def nextbiz(d):
    x = d + TD(days=1)
    for _ in range(400):
        if isbiz(x):
            return x
        x = x + TD(days=1)
    return x
def nth_biz_after(d, n):
    x = d
    k = 1 if (CAL.get('count_today') and isbiz(d)) else 0
    for _ in range(400):
        if k >= n:
            return x
        x = x + TD(days=1)
        if isbiz(x):
            k += 1
    return x
def week_end_biz(d):
    """Last business day of d's calendar week (Monday to Sunday), or None if there is none."""
    monday = d - TD(days=d.weekday())
    x = monday + TD(days=6)
    while x >= monday:
        if isbiz(x):
            return x
        x = x - TD(days=1)
    return None
def this_weekday(today, i):
    return today - TD(days=today.weekday()) + TD(days=i)
def next_weekday(today, i):
    return this_weekday(today, i) + TD(days=7)

CFG = json.loads('{"fields":{"customer":"customer_id","product":"product_id","amount":"amount","date":"date","queue":"queue","note_reason":"reason","outcome":"outcome","reason":"reason"},"tool":"create_promise"}')

try:
    b = config.get('body')
    F = CFG.get('fields') or dict()
    if isinstance(b, dict):
        tool = str(CFG.get('tool') or '')
        for key in ('product', 'amount', 'date'):
            f = F.get(key) or key
            v = b.get(f)
            if v is None or str(v).strip() == '' or '{' in str(v):
                for cand in (tool + '_args.' + tool + '_' + f, tool + '_args.' + f):
                    if vars.get(cand) not in (None, ''):
                        b[f] = vars.get(cand)
                        break
        ids = [s for s in str(vars.get('prod_ids') or '').split(',') if s]
        pf = F.get('product') or ''
        pid = str(b.get(pf) or '').strip()
        if pid not in ids and ids:
            if len(ids) == 1:
                pid = ids[0]
            else:
                for k, s in enumerate(ids):
                    if pid.lower() in (str(k + 1), 'product ' + str(k + 1), s.lower()):
                        pid = s
        b[pf] = pid
        dls = json.loads(str(vars.get('deadlines_json') or '') or 'null') or dict()
        df = F.get('date') or 'date'
        ds = str(b.get(df) or '')[:10]
        if dls.get(pid) and len(ds) == 10:
            d, dd = D.fromisoformat(ds), D.fromisoformat(dls.get(pid))
            if d > dd:
                d = dd
            elif not isbiz(d):
                nb = nextbiz(d)
                d = nb if nb <= dd else dd
            b[df] = d.isoformat()
        af = F.get('amount') or 'amount'
        try:
            amt = float(str(b.get(af)).replace(',', ''))
            lim = (json.loads(str(vars.get('limits_json') or '') or 'null') or dict()).get(pid)
            if lim and lim[1] is not None and amt > float(lim[1]):
                amt = float(lim[1])
            b[af] = round(amt, 2)
        except Exception:
            pass
        config['body'] = b
except Exception:
    pass

